 * @param {number} x
 * @param {number[]} queries
 * @return {number[]}
 */
var countServers = function(n, logs, x, queries) {
    const map = new Map();

    for (const [server, time] of logs) {
        if (!map.has(time)) {
            map.set(time, []);
        }
        map.get(time).push(server);
    }

    const res = [];

    for (const query of queries) {
        let withReq = [];

        for (let i = query - x; i <= query; i++) {
            withReq = withReq.concat(map.get(i) || []);
