        res.push(n - new Set(withReq).size);
    }

    return res;
};

/**
 * @param {number} n
 * @param {number[][]} logs
 * @param {number} x
 * @param {number[]} queries
 * @return {number[]}
 */
var countServers = function(n, logs, x, queries) {
    const map = new Map();

    for (const [server, time] of logs) {
        if (!map.has(time)) {
            map.set(time, []);
        }
        map.get(time).push(server);
    }

    let minQuery = Infinity;
    let maxQuery = -Infinity;

    for (const query of queries) {
        minQuery = Math.min(minQuery, query);
        maxQuery = Math.max(maxQuery, query);
    }

    const queryMap = new Map([...new Set(queries)].map(time => [time, 0]));
    const freq = new Map();

    for (let i = minQuery - x; i <= maxQuery; i++) {
        const servers = map.get(i) || [];

        for (const server of servers) {
            freq.set(server, (freq.get(server) || 0) + 1);
        }

        if (i < minQuery) continue;

        const prevServers = map.get(i - x - 1) || [];

        for (const server of prevServers) {
            const cur = freq.get(server) - 1;
            if (cur <= 0) {
                freq.delete(server);
            } else {
                freq.set(server, cur);
            }
        }

        if (queryMap.has(i)) {
            queryMap.set(i, n - freq.size);
        }
    }

    return queries.map(x => queryMap.get(x));
};

